const OPM = "https://www.opm.gov/policy-data-oversight/pay-leave/federal-holidays/";
export function holidays(y) { const nth = (m, dow, n) => { const d = new Date(Date.UTC(y, m, 1)); let c = 0; while (true) { if (d.getUTCDay() === dow && ++c === n) break; d.setUTCDate(d.getUTCDate() + 1) } return day(d) }, last = (m, dow) => { const d = new Date(Date.UTC(y, m + 1, 0)); while (d.getUTCDay() !== dow) d.setUTCDate(d.getUTCDate() - 1); return day(d) }, f = (m, d) => y + "-" + String(m).padStart(2, "0") + "-" + String(d).padStart(2, "0");
  const H = (date, name, tags, source) => ({ date, name, tags, source: source || "" });
  return [H(f(1, 1), "New Year's Day", ["general", "celebration"], OPM), H(nth(0, 1, 3), "Martin Luther King Jr. Day", ["general", "culture", "community"], OPM), H(f(2, 1), "Black History Month", ["culture", "community", "general"], "https://www.blackhistorymonth.gov/"), H(f(2, 14), "Valentine's Day", ["lifestyle", "food", "nightlife", "music"]),
    H(f(3, 1), "Women's History Month", ["culture", "community", "general"], "https://womenshistorymonth.gov/"), H(nth(4, 0, 2), "Mother's Day", ["lifestyle", "food", "general"]), H(last(4, 1), "Memorial Day", ["general"], OPM), H(f(5, 1), "Graduation season", ["careers", "education", "general"]),
    H(f(6, 19), "Juneteenth", ["culture", "community", "general", "music"], OPM), H(nth(5, 0, 3), "Father's Day", ["lifestyle", "food", "general"]), H(f(7, 4), "Independence Day", ["general", "celebration", "travel"], OPM), H(f(8, 1), "Back-to-school season", ["education", "careers", "general"]),
    H(nth(8, 1, 1), "Labor Day", ["careers", "general", "travel"], OPM), H(f(10, 1), "Homecoming season", ["music", "nightlife", "community", "culture"]), H(f(10, 31), "Halloween", ["nightlife", "music", "lifestyle", "food", "books", "games"]), H(nth(10, 4, 4), "Thanksgiving", ["general", "food", "travel", "community"], OPM),
    H(f(12, 24), "Christmas Eve", ["general", "celebration"]), H(f(12, 25), "Christmas Day", ["general", "celebration"], OPM), H(f(12, 31), "New Year's Eve", ["nightlife", "music", "celebration", "general"])] }
export function upcomingHolidays(now, days) { const out = [], end = addDays(now, days || 30), t = day(now); for (const y of [now.getUTCFullYear(), now.getUTCFullYear() + 1]) for (const h of holidays(y)) if (h.date >= t && h.date <= day(end)) out.push(Object.assign({ daysAway: Math.round((Date.parse(h.date) - Date.parse(t)) / 864e5) }, h)); return out.sort((a, b) => a.date.localeCompare(b.date)) }
const TAGS = { ent: ["music", "nightlife", "culture", "celebration", "community", "general"], music: ["music", "culture", "celebration"], live: ["music", "nightlife", "celebration", "community"], tv: ["music", "culture", "celebration", "general"], guide: ["travel", "general", "community"], vybr8: ["food", "nightlife", "lifestyle", "celebration", "community"],
  pathd: ["careers", "education", "community", "general"], aec: ["education", "careers"], aelio: ["education"], scu: ["books", "games", "culture", "education"] };
